import java.nio.file.*;import java.sql.*;import java.util.*;
class CatalogSurvey {
 static List<Map<String,Object>> rows(Connection c,String sql)throws Exception {var list=new ArrayList<Map<String,Object>>();try(var s=c.createStatement();var r=s.executeQuery(sql)){var md=r.getMetaData();while(r.next()){var row=new LinkedHashMap<String,Object>();for(int i=1;i<=md.getColumnCount();i++)row.put(md.getColumnLabel(i),r.getObject(i));list.add(row);}}return list;}
 public static void main(String[] args)throws Exception {try{var p=new Properties();try(var r=Files.newBufferedReader(Path.of("src/main/resources/application-mysql.properties"))){p.load(r);}var out=new LinkedHashMap<String,Object>();try(var c=DriverManager.getConnection(p.getProperty("spring.datasource.url"),p.getProperty("spring.datasource.username"),p.getProperty("spring.datasource.password"))){c.setAutoCommit(false);out.put("schema",rows(c,"select database() as name"));out.put("categories",rows(c,"select id,name,slug,is_active from categories order by id"));out.put("toppings",rows(c,"select id,name,price,is_active from toppings order by id"));out.put("stores",rows(c,"select id,name,slug,status,accepting_orders from stores order by id"));out.put("products",rows(c,"select id,store_id,category_id,name,slug,catalog_key,base_price,is_active,is_available from products order by store_id,id"));out.put("variants",rows(c,"select product_id,size_name,extra_price,is_active,(stock_quantity is null) as untracked_stock from product_variants order by product_id,size_name"));out.put("product_toppings",rows(c,"select product_id,topping_id from product_toppings order by product_id,topping_id"));out.put("store_toppings",rows(c,"select store_id,topping_id,is_available from store_toppings order by store_id,topping_id"));c.rollback();}Files.writeString(Path.of(args[0]),new com.fasterxml.jackson.databind.ObjectMapper().writerWithDefaultPrettyPrinter().writeValueAsString(out));System.out.println("Safe catalog survey complete; no user rows or credentials exported.");}catch(Exception e){System.err.println("Survey failed: "+e.getClass().getSimpleName()+ (e instanceof SQLException q?" state="+q.getSQLState()+" code="+q.getErrorCode():""));System.exit(1);}}
}
